          "claim": "ts-basic's outgoing HTTP client calls are the failing spans: about 283 Error calls at ~3.6 s p95, while its station calls stay Unset and fast."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-basic-service' AND attr_log_template LIKE '%Connection refused%' GROUP BY 1,2",
          "claim": "ts-basic logs SEVERE 503 errors: upstream connect error, delayed connect error, connection refused, on its requests to downstream services."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_k8s_pod_name pod, count(*) n, max(time) last_seen FROM abnormal_traces WHERE service_name IN ('ts-price-service','ts-train-service','ts-route-service') GROUP BY 1,2",
          "claim": "Price and train server spans nearly vanish after the first 0.1 s, while their pods keep emitting metrics with normal CPU and memory."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Client' AND span_name LIKE 'POST%' GROUP BY 1,2 ORDER BY n DESC",
          "claim": "ts-travel-service's POST calls to ts-basic-service return Error with about 60 s median duration, far slower than basic's own 3.5 s server time."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Client' AND span_name LIKE 'POST%' GROUP BY 1,2 ORDER BY n DESC",
          "claim": "ts-travel2-service's POST calls to ts-basic-service return Error with about 60 s median duration."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.span_name, c.attr_status_code, count(*) n, quantile_cont(c.duration,0.5)/1e6 p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "ts-route-plan-service calls to ts-travel-service end in Error after about 60 s, matching travel-service's slowed basic-dependent requests."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.span_name, s.attr_status_code, count(*) n, quantile_cont(s.duration,0.5)/1e6 p50_ms FROM abnormal_traces s WHERE s.service_name='ts-route-plan-service' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY n DESC",
          "claim": "ts-route-plan-service server spans return Error after about 60 s, the calls ts-travel-plan-service depends on."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
